const MENU_BUTTON_TEXT = document.getElementById("hideNavbarButtonText");
const MENU_BUTTON = document.getElementById("navbarToggleButton");
const NAV_MENU = document.getElementById("navigationMenu");

MENU_BUTTON.addEventListener("click", function () {

    if (NAV_MENU.style.display === "block") {

        MENU_BUTTON_TEXT.innerHTML = "Menu >";
        NAV_MENU.style.display = "none";

    } else {

        MENU_BUTTON_TEXT.innerHTML = "Hide >";
        NAV_MENU.style.display = "block";

    }

});


window.addEventListener("resize", function () {

    if (window.innerWidth > 650) {

        MENU_BUTTON_TEXT.innerHTML = "Hide >";
        NAV_MENU.style.display = "block";

    }

    if (window.innerWidth < 650) {

        MENU_BUTTON_TEXT.innerHTML = "Menu >";
        NAV_MENU.style.display = "none";

    }

});



// ==========================
// BACKGROUND MUSIC TOGGLE
// ==========================

const GLOBAL_SOUND_TOGGLE = document.getElementById("navSoundToggle");

const backgroundMusic = new Audio("./music/background.mp3");

backgroundMusic.loop = true;
backgroundMusic.volume = 0.5;


// Load saved settings
let musicOn = localStorage.getItem("musicOn") === "true";
const savedTime = localStorage.getItem("musicTime");

if (savedTime) {
    backgroundMusic.currentTime = parseFloat(savedTime);
}


// Update button text
GLOBAL_SOUND_TOGGLE.innerHTML = musicOn ? "Music On" : "Music Off";


// Resume music automatically if it was previously on
if (musicOn) {
    backgroundMusic.play().catch(function(error) {
        console.log("Autoplay prevented:", error);
    });
}


GLOBAL_SOUND_TOGGLE.addEventListener("click", function () {

    musicOn = !musicOn;

    localStorage.setItem("musicOn", musicOn);

    if (musicOn) {

        backgroundMusic.play();
        GLOBAL_SOUND_TOGGLE.innerHTML = "Music On";

    } else {

        backgroundMusic.pause();
        GLOBAL_SOUND_TOGGLE.innerHTML = "Music Off";

    }

});


// Save playback position every second
setInterval(function () {

    if (musicOn) {
        localStorage.setItem("musicTime", backgroundMusic.currentTime);
    }

}, 1000);


// Save one last time before leaving the page
window.addEventListener("beforeunload", function () {

    localStorage.setItem("musicTime", backgroundMusic.currentTime);

});

